function MacroAnalysisPage({ go }) {
  const [values, setValues] = useState({ age: 25, gender: 'erkek', height: 175, weight: 75, activity: 1.55, goal: 0, protein: 30 })
  const [result, setResult] = useState(null)
  const update = (key, value) => setValues((current) => ({ ...current, [key]: value }))
  const submit = (event) => { event.preventDefault(); const bmr = 10 * values.weight + 6.25 * values.height - 5 * values.age + (values.gender === 'kadın' ? -161 : 5); const calories = bmr * values.activity + values.goal; const proteinPercent = values.protein, fatPercent = 25, carbPercent = 100 - proteinPercent - fatPercent; const protein = Math.round(calories * proteinPercent / 400); const fat = Math.round(calories * fatPercent / 900); const carbs = Math.round(calories * carbPercent / 400); setResult({ calories: Math.round(calories), protein, fat, carbs, proteinPercent, fatPercent, carbPercent }) }
  const slider = (key, label, unit, min, max) => <label className="analysis-field"><div className="field-heading"><span>{label}</span><b>{values[key]} {unit}</b></div><input type="range" min={min} max={max} value={values[key]} style={{ '--range-progress': ((((Number(values[key]) - min) / (max - min)) * 100) + '%') }} onChange={(event) => update(key, Number(event.target.value))} /></label>
  return <section className="analysis-page"><div className="analysis-hero"><button className="back-link" onClick={() => go('tools')}>← Tüm araçlara dön</button><div className="analysis-category">BESLENME PLANLAMA</div><h1>Makro Hesaplama</h1><p>Protein, karbonhidrat ve yağ ihtiyacınızı hedefinize göre hesaplayın.</p></div><div className="analysis-layout macro-layout"><div className="analysis-calculator macro-calculator"><h2>Bilgileriniz</h2><form onSubmit={submit}><div className="macro-pair">{slider('age', 'Yaş', '', 14, 80)}<label>Cinsiyet<select value={values.gender} onChange={(event) => update('gender', event.target.value)}><option value="erkek">Erkek</option><option value="kadın">Kadın</option></select></label></div><div className="macro-pair">{slider('height', 'Boy', 'cm', 140, 220)}{slider('weight', 'Kilo', 'kg', 40, 180)}</div><label>Aktivite<select value={values.activity} onChange={(event) => update('activity', Number(event.target.value))}><option value="1.2">Hareketsiz</option><option value="1.375">Hafif aktif</option><option value="1.55">Orta aktif</option><option value="1.725">Çok aktif</option></select></label><fieldset className="macro-goals"><legend>Hedef</legend>{[[-400,'↘','KİLO VER'],[0,'◎','KORU'],[300,'↗','KAS YAP']].map(([goal, icon, label]) => <button type="button" className={values.goal === goal ? 'selected' : ''} key={label} onClick={() => update('goal', goal)}><span>{icon}</span>{label}</button>)}</fieldset>{slider('protein', 'Protein oranı', '%', 20, 40)}<small>Yağ %25 sabit, kalan enerji karbonhidrattan hesaplanır.</small><button className="button primary" type="submit">HESAPLA</button></form></div><div className="analysis-result macro-result">{result ? <><div className="result-kicker">GÜNLÜK MAKRO HEDEFİN</div><h2>{result.calories} kcal</h2><div className="macro-chart" style={{ '--protein': `${result.proteinPercent}%`, '--fat': `${result.proteinPercent + result.fatPercent}%` }}><span>{result.calories}<small>kcal</small></span></div><div className="macro-result-grid"><div className="protein"><span>Protein</span><strong>{result.protein} g</strong><b>%{result.proteinPercent}</b></div><div className="fat"><span>Yağ</span><strong>{result.fat} g</strong><b>%{result.fatPercent}</b></div><div className="carb"><span>Karbonhidrat</span><strong>{result.carbs} g</strong><b>%{result.carbPercent}</b></div></div></> : <><div className="result-icon">◎</div><h2>Sonuç bekleniyor</h2><p>Bilgilerinizi girin ve hesapla butonuna basın.</p></>}</div></div></section>
}

function AnalysisTools({ go }) { return <section className="tools-page"><div className="tools-intro"><span>ANALİZ ARAÇLARI</span><h1>VÜCUDUNU <i>ANALİZ ET</i></h1><p>Vücudunu daha iyi tanı, hedeflerine uygun değerleri saniyeler içinde hesapla. Ücretsiz analiz araçlarıyla gelişimini ölçmeye hemen başla.</p></div><div className="tools-grid">{toolData.map(([, title, , type], index) => type === 'BMI' ? null : <button className={`tool-card tool-${index}`} key={title} onClick={() => go(`tool-${type.toLowerCase()}`)}><span className="tool-icon"><ToolIcon type={type} /></span><em>{index < 2 ? 'SAĞLIK' : index < 5 ? 'BESLENME' : 'ANALİZ'}</em><h2>{title}</h2><b>DETAYLARI GÖR →</b></button>)}</div></section> }

const articleContent = { BKI: { category: 'SAĞLIK HESAPLAYICI', title: 'Boy Kilo Endeksi', subtitle: 'Boyunuza göre ideal kilonuzda olup olmadığınızı öğrenin ve sağlığınızı değerlendirin', heading: 'Boy Kilo Endeksi Nedir? Nasıl Hesaplanır?', paragraphs: ['Boy Kilo Endeksi, vücut ağırlığını boy ile karşılaştırarak genel bir sağlık değerlendirmesi sunan pratik bir göstergedir. Tek başına tanı koydurmaz; vücut kompozisyonu ve yaşam tarzı verileriyle birlikte yorumlanmalıdır.', 'Boy ve kilo ölçümlerini mümkün olduğunca aynı koşullarda almak, zaman içindeki değişimleri daha güvenilir takip etmenizi sağlar. Sabah ölçümü ve aylık takip, günlük dalgalanmaların etkisini azaltır.', 'Endeks değerini bel çevresi, vücut yağ yüzdesi ve performans verileriyle birlikte değerlendirmek daha bütünsel bir tablo verir. Sağlık endişeniz varsa bir sağlık profesyoneline danışın.'], faqs: ['Boy kilo endeksi nedir?', 'Boy kilo endeksi nasıl yorumlanır?', 'Endeksim yüksek çıktı, ne yapmalıyım?', 'Kas kütlesi yüksek bireylerde BKİ güvenilir midir?'], faqAnswers: { 'Boy kilo endeksi nedir?': 'Boy kilo endeksi, diğer adıyla Beden Kitle İndeksi (BKİ), kişinin kilosunun boyuna göre değerlendirilmesini sağlayan pratik bir ölçüm yöntemidir. Vücut ağırlığının, boy uzunluğunun karesine bölünmesiyle hesaplanır. BKİ genel bir fikir verse de kas kütlesi, yağ oranı ve vücut kompozisyonunu doğrudan göstermez. Bu nedenle özellikle sporcularda ve yüksek kas kütlesine sahip kişilerde tek başına yeterli bir değerlendirme yöntemi değildir.', 'Kas kütlesi yüksek bireylerde BKİ güvenilir midir?': 'Beden Kitle İndeksi (BKİ), yalnızca boy ve kilo üzerinden hesaplandığı için kas ve yağ kütlesi arasındaki farkı ayırt edemez. Bu nedenle kas oranı yüksek sporcularda BKİ değeri normalden yüksek çıkabilir ve kişi fazla kilolu olarak sınıflandırılabilir. Daha doğru bir değerlendirme için BKİ; yağ oranı, bel çevresi, vücut kompozisyonu ve kişinin genel sağlık ve performans durumu ile birlikte değerlendirilmelidir.' } }, BMI: { category: 'SAĞLIK ANALİZİ', title: 'Vücut Kitle İndeksi', subtitle: 'Boy ve kilonuza göre BMI değerinizi hesaplayın', heading: 'Vücut Kitle İndeksi Nedir?', paragraphs: ['Vücut Kitle İndeksi (VKİ), kilogram cinsinden ağırlığın metre cinsinden boyun karesine bölünmesiyle hesaplanır: VKİ = kilo / boy².', 'VKİ, popülasyon düzeyinde yararlı bir başlangıç göstergesidir ancak kas ve yağ dokusunu birbirinden ayıramaz. Bu yüzden sporcularda ve kas kütlesi yüksek kişilerde tek başına yanıltıcı olabilir.', 'Sonucunuzu bel çevresi ve vücut yağ oranı gibi tamamlayıcı ölçümlerle birlikte değerlendirin.'], faqs: ['BMI nedir ve nasıl hesaplanır?', 'Kadın ve erkek için BMI farklı mıdır?'], faqAnswers: { 'BMI nedir ve nasıl hesaplanır?': 'BMI (Body Mass Index), Türkçede Beden Kitle İndeksi (BKİ) olarak adlandırılır ve kişinin kilosunun boyuna göre değerlendirilmesini sağlayan bir ölçüttür. Hesaplama, vücut ağırlığının kilogram cinsinden değerinin boy uzunluğunun metre cinsinden karesine bölünmesiyle yapılır.\n\nBMI = Kilo (kg) / Boy² (m)\n\nBMI genel bir değerlendirme sağlar ancak kas kütlesi, yağ oranı ve vücut kompozisyonu hakkında doğrudan bilgi vermez. Bu nedenle sonuç, kişinin bireysel özellikleri ve diğer sağlık göstergeleriyle birlikte değerlendirilmelidir.', 'Kadın ve erkek için BMI farklı mıdır?': 'BMI hesaplama formülü kadın ve erkeklerde aynıdır ve yetişkinler için kullanılan genel sınıflandırma aralıkları cinsiyete göre değişmez. Ancak kadın ve erkeklerin kas kütlesi, yağ oranı ve yağ dağılımı farklılık gösterebildiği için aynı BMI değeri her bireyde aynı vücut kompozisyonunu ifade etmeyebilir. Bu nedenle BMI sonucunun; bel çevresi, yağ oranı ve genel vücut kompozisyonu gibi diğer ölçümlerle birlikte değerlendirilmesi daha doğru olur.' } }, CALORIE: { category: 'BESLENME ANALİZİ', title: 'Kalori Hesaplama', subtitle: 'Hedefinize göre günlük kalori ihtiyacınızı hesaplayın', heading: 'Kalori Nedir? Nasıl Hesaplanır?', paragraphs: ['Kalori, besinlerin vücudunuza sağladığı enerjiyi ifade eder. Günlük ihtiyaç; yaş, boy, kilo, cinsiyet, aktivite ve hedefe göre değişir.', 'Bu araç bazal metabolizma hızını Mifflin-St Jeor denklemiyle tahmin eder ve aktivite katsayısıyla günlük enerji harcamasını hesaplar.', 'Hesaplanan değer bir başlangıç noktasıdır. İki-üç haftalık kilo ve performans takibine göre koçunla birlikte ince ayar yapılmalıdır.'], faqs: ['Günlük kalori ihtiyacı nasıl hesaplanır?', 'Kilo vermek için kaç kalori almalıyım?', 'Kalori açığı oluşturdum ama kilo veremiyorum, neden?', 'Kas yapmak için ne kadar kalori fazlası gerekir?'], faqAnswers: { 'Günlük kalori ihtiyacı nasıl hesaplanır?': 'Günlük kalori ihtiyacı önce vücudun dinlenme hâlinde harcadığı enerji, yani bazal metabolizma hızı (BMR) tahmin edilerek hesaplanır. BMR; yaş, cinsiyet, boy ve kiloya göre belirlenir. Ardından bu değer günlük hareket ve antrenman düzeyini temsil eden aktivite katsayısıyla çarpılarak toplam günlük enerji harcaması (TDEE) bulunur.\n\nTDEE = BMR × Aktivite Katsayısı\n\nHesaplanan değer bir başlangıç tahminidir. Gerçek ihtiyaç; günlük hareket, antrenman yoğunluğu, vücut kompozisyonu ve metabolik farklılıklara göre değişebilir. En doğru yaklaşım, kalori hedefini birkaç haftalık kilo, çevre ölçümü ve performans takibine göre güncellemektir.', 'Kilo vermek için kaç kalori almalıyım?': 'Kilo vermek için günlük enerji alımının toplam enerji harcamasından düşük olması gerekir. Çoğu yetişkin için koruma kalorisinden yaklaşık 300–500 kcal daha düşük bir hedef, sürdürülebilir bir başlangıç olabilir. Amaç hızlı sonuç almak yerine kas kaybını ve performans düşüşünü sınırlayan, haftalık olarak takip edilebilir bir hız oluşturmaktır.\n\nİki–üç hafta boyunca haftalık kilo ortalaması değişmiyorsa porsiyonlar, kayıt doğruluğu ve günlük hareket gözden geçirilerek hedef küçük adımlarla güncellenebilir. Çok düşük kalorili planlar uzman değerlendirmesi olmadan uygulanmamalıdır.', 'Kalori açığı oluşturdum ama kilo veremiyorum, neden?': 'Tartının kısa süre değişmemesi her zaman yağ kaybının durduğu anlamına gelmez. Su tutulumu, tuz ve karbonhidrat tüketimi, sindirim sistemi doluluğu, adet döngüsü ve yoğun antrenmanlar vücut ağırlığını geçici olarak etkileyebilir. Ayrıca porsiyonların eksik kaydedilmesi, içecek ve atıştırmaların hesaba katılmaması ya da günlük hareketin farkında olmadan azalması planlanan açığı kapatabilir.\n\nTek bir ölçüm yerine en az iki–üç haftalık sabah tartısı ortalamasını, bel çevresini ve aktivite düzeyini birlikte takip etmek daha anlamlıdır. Tutarlı takibe rağmen değişim yoksa kalori hedefi yeniden hesaplanmalı; ilaçlar veya sağlık sorunları ihtimali varsa sağlık profesyoneline danışılmalıdır.', 'Kas yapmak için ne kadar kalori fazlası gerekir?': 'Kas kazanımı için direnç antrenmanı, yeterli protein ve toparlanmayla birlikte ölçülü bir enerji fazlası kullanılabilir. Günlük yaklaşık 250–500 kcal fazlalık pratik bir başlangıç aralığıdır; ancak ihtiyaç kişinin antrenman geçmişine, kilosuna ve mevcut yağ oranına göre değişir. Daha büyük fazlalıklar kas kazanımını aynı oranda hızlandırmadan yağlanmayı artırabilir.\n\nHaftalık kilo ortalaması, bel çevresi, kuvvet artışı ve antrenman performansı düzenli izlenmelidir. Kilo çok hızlı artıyorsa fazlalık azaltılmalı, birkaç hafta boyunca artış yoksa küçük bir kalori eklemesi yapılmalıdır.' } }, TDEE: { category: 'ENERJİ ANALİZİ', title: 'TDEE Hesaplama', subtitle: 'Günlük toplam enerji harcamanızı hesaplayın', heading: 'TDEE Nedir? Nasıl Hesaplanır?', paragraphs: ['TDEE, bir günde vücudunuzun temel yaşamsal işlevler, hareket ve egzersiz dahil harcadığı toplam enerjidir.', 'Önce bazal metabolizma hızı hesaplanır, ardından seçilen aktivite katsayısıyla çarpılır. Kilonuzu koruma kaloriniz yaklaşık olarak bu değerdir.', 'Gerçek TDEE kişiden kişiye değişir. Hesabı bir referans olarak kullanın ve düzenli ölçümlerle kişiselleştirin.'], faqs: ['TDEE ile BMR arasındaki fark nedir?'], faqAnswers: { 'TDEE ile BMR arasındaki fark nedir?': 'BMR, vücudun dinlenme hâlinde harcadığı enerjidir. TDEE ise BMR’ye günlük hareket ve egzersizlerle harcanan enerjinin eklenmiş hâlidir.' } }, MACRO: { category: 'BESLENME PLANLAMA', title: 'Makro Hesaplama', subtitle: 'Protein, karbonhidrat ve yağ ihtiyacınızı hesaplayın', heading: 'Makro Besinler Nedir? Nasıl Hesaplanır?', paragraphs: ['Makrolar protein, karbonhidrat ve yağdan oluşur. Protein ve karbonhidrat gram başına 4, yağ ise 9 kcal enerji sağlar.', 'Bu hesaplayıcı önce hedef kalorinizi belirler, ardından protein önceliğiyle kalan enerjiyi karbonhidrat ve yağ arasında dağıtır.', 'Makro hedefleri bir kural değil, sürdürülebilir beslenme için esnek bir başlangıç çerçevesidir.'], faqs: ['Makro besinler nelerdir?', 'Kilo vermek için en iyi makro oranı nedir?', 'Kas yapmak için protein ne kadar olmalı?', 'Makro takibi yapmak şart mı?'] }, IDEAL: { category: 'HEDEF BELİRLEME', title: 'İdeal Kilo', subtitle: 'Boyunuza ve cinsiyetinize göre bilimsel formülle ideal kilonuzu hesaplayın', heading: 'İdeal Kilo Nedir? Nasıl Hesaplanır?', paragraphs: ['İdeal kilo tek bir doğru sayı değil, boy, cinsiyet, kemik yapısı, kas kütlesi ve yaşam tarzına göre değişen bir aralıktır.', 'Formül sonucu yalnızca rehber olarak değerlendirilmelidir. Özellikle sporcularda vücut kompozisyonu, kilo sayısından daha anlamlı olabilir.', 'Sağlıklı ve sürdürülebilir değişim için hedefi düzenli antrenman, yeterli protein ve gerçekçi bir zaman planıyla birlikte belirleyin.'], faqs: ['İdeal kilo nasıl hesaplanır?'], faqAnswers: { 'İdeal kilo nasıl hesaplanır?': 'İdeal kilo; boy ve cinsiyet bilgilerine dayanan formüllerle tahmini olarak hesaplanır. Sonuç tek bir kesin değer değil, kişiye göre değişebilen bir referanstır.' } }, FAT: { category: 'VÜCUT ANALİZİ', title: 'Yağ Oranı', subtitle: 'US Navy formülüyle vücut yağ yüzdenizi hesaplayın', heading: 'Vücut Yağ Oranı Nedir?', paragraphs: ['Vücut yağ oranı, toplam ağırlığın ne kadarının yağ dokusundan oluştuğunu gösterir. Vücut kompozisyonunu takip etmek için kilo değerinden daha açıklayıcı olabilir.', 'US Navy yöntemi boyun, bel ve cinsiyete göre tahmin yapar. Ölçümleri aynı noktadan ve aynı koşullarda almak sonucu iyileştirir.', 'Düşük yağ oranı her zaman daha iyi değildir. Performans, hormon dengesi ve genel sağlık birlikte değerlendirilmelidir.'], faqs: ['Vücut yağ oranı neden önemlidir?', 'Kadın ve erkek yağ oranı neden farklıdır?'], faqAnswers: { 'Vücut yağ oranı neden önemlidir?': 'Vücut yağ oranı, toplam kilonun ne kadarının yağ dokusundan oluştuğunu gösterir. Sağlık durumunu ve fiziksel gelişimi yalnızca kiloya göre daha doğru değerlendirmeye yardımcı olur.', 'Kadın ve erkek yağ oranı neden farklıdır?': 'Kadınların hormon yapısı ve doğal yağ depolama ihtiyacı nedeniyle sağlıklı yağ oranları genellikle erkeklerden daha yüksektir.' } }, '1RM': { category: 'GÜÇ ANALİZİ', title: 'One Rep Max', subtitle: 'Maksimum kaldırabileceğiniz ağırlığı güvenli şekilde tahmin edin', heading: '1 Tekrar Maksimum Nedir?', paragraphs: ['1RM, bir egzersizde doğru formla kaldırılabilecek tahmini maksimum ağırlıktır. Antrenman yüklerini yüzde olarak planlamaya yardımcı olur.', 'Bu araç submaksimal bir setten tahmin yapar; doğrudan maksimum denemeye göre daha güvenli bir başlangıç sunar.', 'Teknik bozuluyorsa ağırlığı artırmayın. Özellikle yeni başlayanlar ve sağlık problemi olanlar profesyonel gözetimle çalışmalıdır.'], faqs: ['1RM nedir?'], faqAnswers: { '1RM nedir?': '1RM, bir egzersizde doğru formu koruyarak tek tekrarda kaldırabileceğiniz en yüksek ağırlıktır. Antrenman yüklerini belirlemek için referans olarak kullanılır.' } }, WATER: { category: 'HİDRASYON', title: 'Su İhtiyacı', subtitle: 'Günlük su tüketim miktarınızı aktivitenize göre hesaplayın', heading: 'Günlük Su İhtiyacı Nedir?', paragraphs: ['Su ihtiyacı vücut ağırlığı, aktivite, iklim ve terleme miktarına göre değişir. Bu araç temel bir günlük hedef oluşturur.', 'Yoğun ve uzun egzersizlerde sıvı ile birlikte elektrolit dengesi de önem kazanabilir. Aşırı su tüketiminden kaçının.', 'İdrar rengi, susuzluk, performans ve antrenman sonrası kilo değişimi hidrasyonu takip etmek için yardımcı göstergelerdir.'], faqs: ['Günde ne kadar su içmeliyim?'], faqAnswers: { 'Günde ne kadar su içmeliyim?': 'Günlük su ihtiyacı kişiye göre değişir. Genel bir başlangıç olarak vücut ağırlığının kilogramı başına yaklaşık 30–35 ml su tüketilebilir.' } }, HEART: { category: 'KARDİYOVASKÜLER', title: 'Kalp Hızı Bölgeleri', subtitle: 'Karvonen yaklaşımıyla antrenman bölgelerinizi hesaplayın', heading: 'Kalp Atış Hızı Bölgeleri Nedir?', paragraphs: ['Kalp hızı bölgeleri, antrenman yoğunluğunu kişisel kalp hızı aralıklarıyla takip etmeyi sağlar.', 'Maksimum kalp hızı tahmini formüllerle hesaplanır ve bireysel farklılıklar içerebilir. Spor saati ve algısal efor ile birlikte kullanmak daha güvenlidir.', 'Baş dönmesi, göğüs ağrısı veya olağandışı nefes darlığında egzersizi bırakıp sağlık desteği alın.'], faqs: [] }, PROTEIN: { category: 'BESLENME', title: 'Protein İhtiyacı', subtitle: 'Hedefinize göre günlük protein ihtiyacınızı hesaplayın', heading: 'Protein İhtiyacı Nedir?', paragraphs: ['Protein kas, doku, enzim ve hormonların yapı taşlarından biridir. Günlük gereksinim vücut ağırlığı, yaş, aktivite ve hedefe göre değişir.', 'Düzenli direnç antrenmanı yapan kişilerde kilogram başına yaklaşık 1.6–2.2 gram aralığı yaygın bir başlangıç referansıdır.', 'Böbrek hastalığı gibi özel durumlarda protein hedefi sağlık profesyoneliyle belirlenmelidir.'], faqs: ['Günlük protein ihtiyacı nasıl hesaplanır?'] }, REST: { category: 'ZAMANLAYICI', title: 'Dinlenme Süresi', subtitle: 'Antrenman tipine göre ideal set arası dinlenme süresini belirleyin', heading: 'Setler Arası Dinlenme Neden Önemlidir?', paragraphs: ['Dinlenme süresi ATP yenilenmesini, sonraki setteki performansı ve toplam antrenman kalitesini etkiler.', 'Güç çalışmaları daha uzun, hipertrofi ve kondisyon çalışmaları daha kısa dinlenme aralıkları gerektirebilir.', 'Bu aralıklar kılavuzdur; egzersiz tekniği ve toparlanma kalitesi her zaman önceliklidir.'], faqs: [] }, WHR: { category: 'SAĞLIK HESAPLAYICI', title: 'Bel Kalça Oranı', subtitle: 'Karın bölgesindeki yağlanmanızı ölçün ve sağlık riskinizi değerlendirin', heading: 'Bel Kalça Oranı Nedir?', paragraphs: ['Bel-kalça oranı, bel çevresinin kalça çevresine bölünmesiyle bulunur ve yağ dağılımı hakkında fikir verir.', 'Bel ölçümünü göbek hizasında, kalça ölçümünü en geniş noktadan ve aynı koşullarda yapmak gerekir.', 'Bu oran bir tanı değildir. Risk değerlendirmesini yaş, aile öyküsü ve diğer sağlık verileriyle birlikte ele alın.'], faqs: ['Bel kalça oranı nasıl ölçülür?'], faqAnswers: { 'Bel kalça oranı nasıl ölçülür?': 'Bel çevrenizi göbek hizasından, kalça çevrenizi ise en geniş noktadan ölçün. Bel ölçüsünü kalça ölçüsüne bölerek oranı bulabilirsiniz.' } }, TYPE: { category: 'GENETİK ANALİZ', title: 'Vücut Tipi Belirleme', subtitle: 'Ölçümlerini kullanarak baskın vücut tipin hakkında fikir edin', heading: 'Vücut Tipleri Nedir?', paragraphs: ['Ektomorf, mezomorf ve endomorf sınıflaması bir başlangıç çerçevesidir; çoğu kişi bu tiplerin karışımına sahiptir.', 'Vücut tipi kader değildir. Antrenman geçmişi, beslenme, uyku ve yaşam tarzı görünümü zaman içinde güçlü biçimde değiştirir.', 'Bu sonucu programını kişiselleştirmek için bir ipucu olarak kullan; kesin genetik tanı olarak değerlendirme.'], faqs: ['Vücut tipi nedir?'], faqAnswers: { 'Vücut tipi nedir?': 'Vücut tipi, kişinin doğal beden yapısını ve kilo-kas kazanma eğilimini tanımlayan genel bir sınıflandırmadır. Çoğu kişi tek bir tipe değil, tiplerin karışımına sahiptir.' } } }

function toolFields(type) { const field = (key, label, unit = '', min, max) => ({ key, label, unit, type: 'number', min, max }); const heightWeight = [field('height', 'Boy', 'cm', 140, 220), field('weight', 'Kilo', 'kg', 35, 160)]; if (['BKI', 'BMI', 'IDEAL'].includes(type)) return heightWeight; if (['CALORIE', 'TDEE', 'MACRO'].includes(type)) return [field('age', 'Yaş', '', 10, 100), ...heightWeight]; if (type === 'FAT') return [field('height', 'Boy', 'cm', 140, 220), field('weight', 'Kilo', 'kg', 35, 160), field('neck', 'Boyun', 'cm'), field('waist', 'Bel çevresi', 'cm'), field('hip', 'Kalça', 'cm')]; if (type === '1RM') return [field('load', 'Ağırlık', 'kg'), field('reps', 'Tekrar sayısı', '', 1, 15)]; if (type === 'WATER' || type === 'PROTEIN') return [field('weight', 'Kilo', 'kg', 35, 160)]; if (type === 'HEART') return [field('age', 'Yaş', '', 10, 100), field('restingPulse', 'Dinlenme nabzı', 'BPM', 35, 120)]; if (type === 'WHR') return [field('waist', 'Bel çevresi', 'cm'), field('hip', 'Kalça çevresi', 'cm')]; if (type === 'TYPE') return [field('height', 'Boy', 'cm', 140, 220), field('weight', 'Kilo', 'kg', 35, 160), field('wrist', 'Bilek çevresi', 'cm'), field('shoulder', 'Omuz genişliği', 'cm')]; return [] }

function calculateResult(type, values) { const age = Number(values.age), height = Number(values.height), weight = Number(values.weight); const bmi = weight / ((height / 100) ** 2); const activity = Number(values.activity || 1.55); const bmr = 10 * weight + 6.25 * height - 5 * age + (values.gender === 'kadın' ? -161 : 5); const tdee = bmr * activity; if (type === 'BKI' || type === 'BMI') return { main: bmi.toFixed(1), label: bmi < 18.5 ? 'Düşük' : bmi < 25 ? 'Sağlıklı' : bmi < 30 ? 'Yüksek' : 'Riskli', detail: 'Boy kilo endeksi' }; if (type === 'CALORIE') return { main: `${Math.round(tdee - 300)} kcal`, label: 'Hedef kalori', detail: `Koruma kalorisi yaklaşık ${Math.round(tdee)} kcal` }; if (type === 'TDEE') return { main: `${Math.round(tdee)} kcal`, label: 'Günlük toplam enerji', detail: `Bazal metabolizma yaklaşık ${Math.round(bmr)} kcal` }; if (type === 'MACRO') return { main: `${Math.round(weight * 2)} g protein`, label: 'Günlük makro hedefi', detail: `${Math.round(weight * .8)} g yağ · ${Math.round((tdee - weight * 2 * 4 - weight * .8 * 9) / 4)} g karbonhidrat` }; if (type === 'IDEAL') return { main: `${((height - 100) * (values.gender === 'kadın' ? .85 : .9)).toFixed(1)} kg`, label: 'Tahmini ideal kilo', detail: 'Formül tabanlı başlangıç değeri' }; if (type === 'FAT') { const fat = values.gender === 'kadın' ? 163.205 * Math.log10(Number(values.waist) + Number(values.hip) - Number(values.neck)) - 97.684 * Math.log10(height) - 78.387 : 86.01 * Math.log10(Number(values.waist) - Number(values.neck)) - 70.041 * Math.log10(height) + 36.76; return { main: `%${Math.max(0, fat).toFixed(1)}`, label: 'Tahmini yağ oranı', detail: 'US Navy formülü' } } if (type === '1RM') return { main: `${Math.round(Number(values.load) * (1 + Number(values.reps) / 30))} kg`, label: 'Tahmini 1RM', detail: 'Epley formülü' }; if (type === 'WATER') return { main: `${(weight * .035).toFixed(1)} L`, label: 'Günlük su hedefi', detail: 'Aktivite ve iklime göre değişebilir' }; if (type === 'HEART') return { main: `${Math.round(220 - age)} bpm`, label: 'Tahmini maksimum', detail: `Bölge 2: ${Math.round((220 - age) * .6)}–${Math.round((220 - age) * .7)} bpm` }; if (type === 'PROTEIN') return { main: `${Math.round(weight * 1.6)}–${Math.round(weight * 2.2)} g`, label: 'Günlük protein', detail: 'Hedef ve aktiviteye göre başlangıç aralığı' }; if (type === 'REST') return { main: '60–120 sn', label: 'Önerilen dinlenme', detail: 'Güç setlerinde 3–5 dakikaya çıkabilir' }; if (type === 'WHR') { const ratio = Number(values.waist) / Number(values.hip); return { main: ratio.toFixed(2), label: ratio < (values.gender === 'kadın' ? .8 : .9) ? 'Düşük risk' : 'Değerlendirme gerekli', detail: 'Bel / kalça oranı' } } return { main: 'Mezomorf', label: 'Baskın vücut tipi', detail: 'Ölçümler rehber niteliğindedir' } }

const referenceRanges = { BKI: { title: 'Boy Kilo Endeksi Referans Aralıkları', scale: ['14', '18.5', '25', '30', '42'], segments: [['Düşük', 16, '#0ea5e9'], ['Sağlıklı', 23, '#10b981'], ['Yüksek', 18, '#f59e0b'], ['Riskli', 43, '#fb1f59']] }, BMI: { title: 'BMI Referans Aralıkları', scale: ['14', '18.5', '25', '30', '42'], segments: [['Düşük', 16, '#0ea5e9'], ['Sağlıklı', 23, '#10b981'], ['Yüksek', 18, '#f59e0b'], ['Riskli', 43, '#fb1f59']] }, CALORIE: { title: 'Hedef Kalori Referansları', scale: ['BMR', '−500', 'Koruma', '+300', '+500'], segments: [['Düşük hedef', 25, '#0ea5e9'], ['Kilo verme', 25, '#10b981'], ['Koruma', 20, '#f59e0b'], ['Kas kazanımı', 30, '#fb1f59']] }, TDEE: { title: 'Günlük Enerji Referansları', scale: ['BMR', 'Hafif', 'Orta', 'Yoğun', 'Ekstra'], segments: [['Hareketsiz', 22, '#0ea5e9'], ['Hafif aktif', 23, '#10b981'], ['Orta aktif', 25, '#f59e0b'], ['Çok aktif', 30, '#fb1f59']] }, MACRO: { title: 'Makro Dağılım Referansı', scale: ['Protein', 'Yağ', 'Karbonhidrat', 'Dengeli'], segments: [['Protein', 25, '#10b981'], ['Yağ', 25, '#f59e0b'], ['Karbonhidrat', 35, '#0ea5e9'], ['Esnek alan', 15, '#8b5cf6']] }, IDEAL: { title: 'İdeal Kilo Referans Aralığı', scale: ['Alt sınır', 'Önerilen', 'Orta nokta', 'Üst sınır'], segments: [['Alt sınır', 25, '#0ea5e9'], ['Önerilen', 35, '#10b981'], ['Üst sınır', 25, '#f59e0b'], ['Kişisel aralık', 15, '#8b5cf6']] }, FAT: { title: 'Vücut Yağ Oranı Referansı', scale: ['Esansiyel', 'Atletik', 'Fitness', 'Ortalama', 'Yüksek'], segments: [['Esansiyel', 13, '#0ea5e9'], ['Atletik', 20, '#10b981'], ['Fitness', 22, '#f59e0b'], ['Ortalama+', 45, '#fb1f59']] }, '1RM': { title: '1RM Antrenman Bölgeleri', scale: ['50%', '65%', '75%', '85%', '100%'], segments: [['Dayanıklılık', 25, '#0ea5e9'], ['Hipertrofi', 25, '#10b981'], ['Güç', 25, '#f59e0b'], ['Maksimal', 25, '#fb1f59']] }, WATER: { title: 'Günlük Su İhtiyacı Referansı', scale: ['1 L', '2 L', '3 L', '4 L', '5 L'], segments: [['Düşük', 20, '#fb1f59'], ['Temel', 25, '#f59e0b'], ['Önerilen', 30, '#10b981'], ['Aktif', 25, '#0ea5e9']] }, HEART: { title: 'Kalp Hızı Antrenman Bölgeleri', scale: ['50%', '60%', '70%', '80%', '90%', '100%'], segments: [['Bölge 1', 20, '#0ea5e9'], ['Bölge 2', 20, '#10b981'], ['Bölge 3', 20, '#f59e0b'], ['Bölge 4–5', 40, '#fb1f59']] }, PROTEIN: { title: 'Günlük Protein Referansı', scale: ['0.8', '1.2', '1.6', '2.2', '2.5 g/kg'], segments: [['Genel sağlık', 25, '#0ea5e9'], ['Aktif', 25, '#10b981'], ['Kas kazanımı', 30, '#f59e0b'], ['Diyet dönemi', 20, '#fb1f59']] }, REST: { title: 'Set Arası Dinlenme Referansı', scale: ['30 sn', '60 sn', '90 sn', '120 sn', '300 sn'], segments: [['Dayanıklılık', 20, '#0ea5e9'], ['Hipertrofi', 25, '#10b981'], ['Güç', 25, '#f59e0b'], ['Bileşik hareket', 30, '#fb1f59']] }, WHR: { title: 'Bel Kalça Oranı Referansları', scale: ['0.70', '0.80', '0.90', '1.00', '1.10'], segments: [['Düşük risk', 35, '#10b981'], ['Dikkat', 20, '#f59e0b'], ['Orta risk', 20, '#fb8c00'], ['Yüksek risk', 25, '#fb1f59']] }, TYPE: { title: 'Vücut Tipi Referansları', scale: ['İnce yapı', 'Ektomorf', 'Mezomorf', 'Endomorf'], segments: [['Ektomorf', 30, '#0ea5e9'], ['Mezomorf', 35, '#10b981'], ['Geçiş tipi', 15, '#f59e0b'], ['Endomorf', 20, '#fb1f59']] } }
const referenceBounds = { BKI: [14, 42], BMI: [14, 42], CALORIE: [1000, 3500], TDEE: [1200, 4000], IDEAL: [40, 120], FAT: [0, 40], '1RM': [20, 250], WATER: [1, 5], HEART: [80, 210], PROTEIN: [40, 250], REST: [30, 300], WHR: [.7, 1.1] }
function getReferenceStatus(type, result) { if (!result) return null; const range = referenceRanges[type] || referenceRanges.BMI; const exactSegment = range.segments.find(([label]) => label.toLocaleLowerCase('tr-TR') === String(result.label || '').toLocaleLowerCase('tr-TR')); const numeric = Number.parseFloat(String(result.main).replace(/[^0-9.,-]/g, '').replace(',', '.')); const limits = referenceBounds[type]; const marker = Number.isFinite(numeric) && limits ? Math.min(98, Math.max(2, ((numeric - limits[0]) / (limits[1] - limits[0])) * 100)) : null; if (exactSegment) return { marker, color: exactSegment[2], label: exactSegment[0] }; if (marker === null) return null; let edge = 0; const segment = range.segments.find(([, width]) => { edge += width; return marker <= edge }) || range.segments.at(-1); return { marker, color: segment[2], label: segment[0] } }

function ReferenceRange({ type, result }) { const range = referenceRanges[type] || referenceRanges.BMI; const status = getReferenceStatus(type, result); const marker = status?.marker ?? null; return <section className={`reference-panel${result ? ' has-result' : ''}`}><div className="reference-panel-head"><div><div className="section-kicker">REFERANS ARALIĞI</div><h2>{range.title}</h2></div>{result && <span className="reference-current">Senin sonucun: <b style={{ color: status?.color }}>{result.main}</b></span>}</div><div className="reference-bar-wrap"><div className="reference-bar">{range.segments.map(([label, width, color]) => <span key={label} style={{ width: `${width}%`, background: color }} title={label} />)}{marker !== null && <i className="reference-marker" style={{ left: `${marker}%`, background: status?.color, boxShadow: `0 0 14px ${status?.color}` }}><span>SEN</span></i>}</div><div className="reference-scale">{range.scale.map((label) => <span key={label}>{label}</span>)}</div></div><div className="reference-legend">{range.segments.map(([label, , color]) => <span key={label}><i style={{ background: color }} />{label}</span>)}</div></section> }

function AnalysisPage({ type, go }) { const content = articleContent[type] || articleContent.BMI; const [values, setValues] = useState({ gender: 'erkek', activity: '1.55', age: '25', height: '175', weight: '75', waist: '85', hip: '100', neck: '38', reps: '8', load: '60', restingPulse: '60', wrist: '17', shoulder: '45' }); const [result, setResult] = useState(null); const fields = toolFields(type); const update = (key, value) => setValues({ ...values, [key]: value }); const submit = (event) => { event.preventDefault(); setResult(calculateResult(type, values)) }; const related = useMemo(() => toolData.filter((item) => item[3] !== type && item[3] !== 'BMI').map((item) => ({ item, order: Math.random() })).sort((a, b) => a.order - b.order).slice(0, 4).map(({ item }) => item), [type]); const referenceStatus = getReferenceStatus(type, result); return <section className="analysis-page"><div className="analysis-hero"><button className="back-link" onClick={() => go('tools')}>← Tüm araçlara dön</button><div className="analysis-category">{content.category}</div><h1>{content.title}</h1><p>{content.subtitle}</p></div><div className="analysis-layout"><div className="analysis-calculator"><h2>Bilgileriniz</h2><p>Ölçümlerinizi girin ve hesaplama yapın.</p><form onSubmit={submit}><label>Cinsiyet<select value={values.gender} onChange={(event) => update('gender', event.target.value)}><option value="erkek">Erkek</option><option value="kadın">Kadın</option></select></label>{fields.map((field) => <label className="analysis-field" key={field.key}><div className="field-heading"><span>{field.label}</span><b>{values[field.key]} {field.unit}</b></div><input required type="range" min={field.min || 0} max={field.max || (field.key === 'load' ? 200 : field.key === 'reps' ? 15 : 120)} value={values[field.key] || 0} style={{ '--range-progress': ((((Number(values[field.key] || 0) - (field.min || 0)) / ((field.max || (field.key === 'load' ? 200 : field.key === 'reps' ? 15 : 120)) - (field.min || 0))) * 100) + '%') }} onChange={(event) => update(field.key, event.target.value)} /></label>)}{['CALORIE', 'TDEE', 'MACRO', 'WATER', 'PROTEIN'].includes(type) && <label>Aktivite seviyesi<select value={values.activity} onChange={(event) => update('activity', event.target.value)}><option value="1.2">Hareketsiz</option><option value="1.375">Hafif aktif</option><option value="1.55">Orta aktif · 3–5 gün</option><option value="1.725">Çok aktif</option></select></label>}{type === 'REST' && <label>Antrenman tipi<select value={values.rest || 'hypertrophy'} onChange={(event) => update('rest', event.target.value)}><option value="strength">Güç · 1–5 tekrar</option><option value="hypertrophy">Hipertrofi · 6–12 tekrar</option><option value="endurance">Dayanıklılık · 15+ tekrar</option><option value="hiit">HIIT · Sprint</option></select></label>}<button className="button primary" type="submit">{type === 'TYPE' ? 'Analiz et' : 'Hesapla'} <span>→</span></button></form></div><div className="analysis-result" style={referenceStatus ? { '--result-color': referenceStatus.color } : undefined}>{result ? <><div className="result-kicker">SONUÇ</div><div className="result-main">{result.main}</div><h2>{result.label}</h2><p>{result.detail}</p></> : <><div className="result-icon">◎</div><h2>Sonuç bekleniyor</h2><p>Bilgilerinizi girin ve hesapla butonuna basın.</p></>}</div></div><ReferenceRange type={type} result={result} /><div className={`analysis-content section-pad${content.faqs.length ? '' : ' no-faq'}`}><div className="content-main"><h2>{content.heading}</h2>{content.paragraphs.map((paragraph) => <p key={paragraph}>{paragraph}</p>)}<div className="reference-box"><h3>{type === 'BKI' || type === 'BMI' ? 'Boy Kilo Endeksi Kategorileri' : `${content.title} için önemli not`}</h3>{type === 'BKI' || type === 'BMI' ? <div className="reference-grid"><span>Düşük<strong>0 – 18.5</strong></span><span>Sağlıklı<strong>18.5 – 25</strong></span><span>Yüksek<strong>25 – 30</strong></span><span>Riskli<strong>30 – 50</strong></span></div> : <><p>Bu hesaplama bilgilendirme amaçlıdır. Sonucu tek başına tıbbi karar vermek için kullanma; kişisel durumun için uzman değerlendirmesi al.</p><button className="note-contact-button" type="button" onClick={() => go('contact')}>Bana ulaş <span>→</span></button></>}</div></div>{content.faqs.length > 0 && <aside className="faq-column"><h3>Sıkça Sorulan Sorular</h3>{content.faqs.map((question) => <details key={question}><summary>{question}</summary><p>{content.faqAnswers?.[question] || 'Bu değer kişisel koşullara göre değişebilir. Sonucu diğer sağlık ve performans göstergeleriyle birlikte değerlendirmen önerilir.'}</p>{type === 'BKI' && ['Boy kilo endeksi nasıl yorumlanır?', 'Endeksim yüksek çıktı, ne yapmalıyım?'].includes(question) && <button className="faq-contact-button" type="button" onClick={() => go('contact')}>Kişisel değerlendirme için iletişime geç <span>→</span></button>}</details>)}</aside>}</div><section className="related-tools"><div className="section-kicker">DİĞER HESAPLAYICILAR</div><h2>Hedefin için diğer araçlar</h2><div className="related-grid">{related.map(([, title, description, relatedType]) => <button key={title} onClick={() => go(`tool-${relatedType.toLowerCase()}`)}><span><ToolIcon type={relatedType} /></span><strong>{title}</strong><small>{description}</small><b>HESAPLA →</b></button>)}</div></section><p className="medical-note">Bu araçlar yalnızca genel bilgilendirme ve takip amacıyla hazırlanmıştır. Tıbbi tanı, tedavi veya kişisel sağlık tavsiyesi yerine geçmez.</p></section> }

function CalculatorModal({ tool, close }) { const [values, setValues] = useState({ gender: 'erkek', age: '', height: '', weight: '', activity: '1.375', waist: '', hip: '', neck: '', reps: '', load: '' }); const [result, setResult] = useState(''); const update = (key, value) => setValues({ ...values, [key]: value }); const calculate = (event) => { event.preventDefault(); const age = Number(values.age), height = Number(values.height), weight = Number(values.weight), bmi = weight / ((height / 100) ** 2); let output = ''; if (['BMI', 'IDEAL'].includes(tool.type)) output = tool.type === 'BMI' ? `${bmi.toFixed(1)} BMI · ${bmi < 18.5 ? 'Zayıf aralık' : bmi < 25 ? 'Normal aralık' : bmi < 30 ? 'Fazla kilolu aralık' : 'Obezite aralığı'}` : `${((height - 100) * (values.gender === 'erkek' ? 0.9 : 0.85)).toFixed(1)} kg ideal kilo`; if (['CALORIE', 'TDEE', 'MACRO'].includes(tool.type)) { const bmr = 10 * weight + 6.25 * height - 5 * age + (values.gender === 'erkek' ? 5 : -161); const tdee = bmr * Number(values.activity); output = tool.type === 'TDEE' ? `${Math.round(tdee)} kcal / gün` : tool.type === 'CALORIE' ? `${Math.round(tdee - 300)} kcal / gün hedef kalori` : `${Math.round(weight * 2)} g protein · ${Math.round(weight * .8)} g yağ · ${Math.round((tdee - weight * 2 * 4 - weight * .8 * 9) / 4)} g karbonhidrat`; } if (tool.type === '1RM') output = `${Math.round(Number(values.load) * (1 + Number(values.reps) / 30))} kg tahmini 1RM`; if (tool.type === 'WATER') output = `${(weight * 0.035).toFixed(1)} litre / gün`; if (tool.type === 'PROTEIN') output = `${Math.round(weight * 1.8)}–${Math.round(weight * 2.2)} g / gün`; if (tool.type === 'HEART') output = `${Math.round(220 - age)} bpm maksimum · ${Math.round((220 - age) * .65)}–${Math.round((220 - age) * .8)} bpm yağ yakım bölgesi`; if (tool.type === 'REST') output = 'Kas geliştirme: 90–120 sn · Güç: 180–300 sn · İzolasyon: 45–75 sn'; if (tool.type === 'WHR') output = `${(Number(values.waist) / Number(values.hip)).toFixed(2)} bel/kalça oranı`; if (tool.type === 'FAT') output = 'Boyun, bel ve boy ölçüleriyle hesaplanabilir yağ oranı sonucu'; if (tool.type === 'TYPE') output = 'Ölçülerine göre koçunla birlikte en doğru vücut tipini belirle'; setResult(output) }; return <div className="calculator-overlay" onClick={close}><div className="calculator-modal" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={close}>×</button><span className="tool-icon">{tool.icon}</span><div className="section-kicker">ÜCRETSİZ HESAPLAMA</div><h2>{tool.title}</h2><form onSubmit={calculate}><label>Cinsiyet<select value={values.gender} onChange={(event) => update('gender', event.target.value)}><option value="erkek">Erkek</option><option value="kadın">Kadın</option></select></label><div className="calc-fields"><label>Yaş<input type="number" min="1" value={values.age} onChange={(event) => update('age', event.target.value)} /></label><label>Boy (cm)<input type="number" min="1" value={values.height} onChange={(event) => update('height', event.target.value)} /></label><label>Kilo (kg)<input type="number" min="1" value={values.weight} onChange={(event) => update('weight', event.target.value)} /></label></div>{tool.type === '1RM' && <div className="calc-fields"><label>Kaldırılan kilo<input type="number" value={values.load} onChange={(event) => update('load', event.target.value)} /></label><label>Tekrar sayısı<input type="number" value={values.reps} onChange={(event) => update('reps', event.target.value)} /></label></div>}{tool.type === 'WHR' && <div className="calc-fields"><label>Bel (cm)<input type="number" value={values.waist} onChange={(event) => update('waist', event.target.value)} /></label><label>Kalça (cm)<input type="number" value={values.hip} onChange={(event) => update('hip', event.target.value)} /></label></div>}<button className="button primary" type="submit">Sonucu hesapla <span>→</span></button></form>{result && <div className="calc-result">{result}</div>}<small>Bu araçlar bilgilendirme amaçlıdır; tıbbi değerlendirme yerine geçmez.</small></div></div> }

export default App
